import React, { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { AnimatePresence, motion, useScroll, useSpring, useTransform } from 'framer-motion';
import { BrowserRouter, Link, Navigate, Route, Routes, useLocation, useNavigate, useParams } from 'react-router-dom';
import { ArrowLeft, ArrowRight, Check, ChevronRight, CircleAlert, CreditCard, Flame, Heart, LockKeyhole, LogOut, MapPin, Menu, Minus, Package, Phone, Plus, ReceiptText, FileText, Search, ShoppingBag, Sparkles, Store, Settings2, X } from 'lucide-react';
